package com.dayflow.listener; import jakarta.servlet.http.*; import java.util.concurrent.atomic.AtomicInteger; public class SessionListener implements HttpSessionListener{private static final AtomicInteger ACTIVE=new AtomicInteger();public void sessionCreated(HttpSessionEvent e){ACTIVE.incrementAndGet();}public void sessionDestroyed(HttpSessionEvent e){ACTIVE.decrementAndGet();}public static int activeSessions(){return ACTIVE.get();}}
